import{z as B,x as s,o as l,c as d,q as r,j as o,D as E,d as e,s as A,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"内核自动调优","description":"","frontmatter":{"title":"内核自动调优","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kernel-autotuning.md","filePath":"llm/kernel-autotuning.md","lastUpdated":1791063341000}'),p={name:"llm/kernel-autotuning.md"};function D(m,a,u,C,h,c){const n=s("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="内核自动调优" tabindex="-1">内核自动调优 <a class="header-anchor" href="#内核自动调优" aria-label="Permalink to &quot;内核自动调优&quot;">​</a></h1><div class="epigraph"><p>同一算法的块大小、流水深度和向量宽度是硬件相关的离散空间；靠编译器或运行时搜一轮，往往比手写一组「通用」常量更接近屋顶。</p><footer>—— Chen et al., TVM, OSDI 2018；Ansor：Zheng et al., OSDI 2020；Triton 的 autotune 为运行时网格搜索</footer></div><p><a href="/llm/torch-compile-inductor">上一课</a>把算子融进 Triton/CUDA。融完之后仍有离散超参：tile、\\(B_r,B_c\\)、warp 数。TVM 把张量程序与自动调度分开；Ansor 用层次化搜索生成调度；Triton <code>@triton.autotune</code> 在若干配置上计时取最快。FlashAttention 的块大小同样是 SRAM 容量约束下的搜索，不是公式给出的唯一整数。本课写 <em>何时搜、缓存键是什么</em>，避免每条请求现场扫网格把 TPOT 打穿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>会计给出的屋顶是上界。实际核用错 tile，有效带宽可能只有峰值一半。<span class="marginnote">术语翻译：tile（瓦片）是把大矩阵切成小块搬进片上内存的方块尺寸；占用率指每个 SM 上同时驻留的线程束占上限的比例。这两个离散数选错，硬件再快也只能跑到峰值的一半——自动调优搜的就是它们。</span><a href="/llm/torch-compile-inductor">上一课</a>的 <code>max-autotune</code> 会触发搜索，首次极慢。服务形状又是动态的：\\(n\\)、\\(B\\)、头数、是否因果、元素类型。缺口是：搜索空间按哪些键缓存，以及动态形状如何落到最近的桶而不每步重搜。</p><p>错误配置不只是慢：共享内存溢出、占用率过低、或数值路径不同（累加顺序）。调优必须验收数值，不能只看毫秒。</p><p><span class="marginnote">CUTLASS / cuBLAS 的启发式选择也是一种自动调优，只是搜索在库内。换一种布局（HND vs BSHD）等于换了一个问题，缓存不能共用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离线：对部署会见到的 \\((B,n,h,d,\\mathrm{dtype})\\) 桶跑 autotune，把最优配置写进磁盘缓存。在线：只允许在冷启动或新桶首次出现时搜，并加超时回退到安全配置。Triton 的 key 应包含动态维的量化桶，而不是原始 \\(n=137\\)。注意力核的 \\(B_c\\) 受 SRAM 与 \\(d\\) 限制，搜索空间其实不大，但 <em>每个 dtype 与是否 GQA</em> 都要单独来。</p><p>与<a href="/llm/flashattention">FlashAttention</a> 家族：FA2/FA3 已在常见头维上调过；自写 Triton 注意力才需要你自己的 autotune。不要在生产路径上对 FA 再套一层网格搜。</p>',10)),(l(),o(i,null,{default:E(()=>[A(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHAPE%5B%22%E5%BD%A2%E7%8A%B6%E6%A1%B6%20B%2Cn%2Ch%2Cdtype%22%5D%20--%3E%20GRID%5B%22%E9%85%8D%E7%BD%AE%E7%BD%91%E6%A0%BC%22%5D%0A%20%20GRID%20--%3E%20TIME%5B%22%E8%AE%A1%E6%97%B6%20%2B%20%E6%95%B0%E5%80%BC%E9%AA%8C%E6%94%B6%22%5D%0A%20%20TIME%20--%3E%20CACHE%5B%22%E7%A3%81%E7%9B%98%20%2F%20%E5%86%85%E5%AD%98%E7%BC%93%E5%AD%98%22%5D%0A%20%20CACHE%20--%3E%20RUN%5B%22%E7%83%AD%E8%B7%AF%E5%BE%84%E5%8F%AA%E6%9F%A5%E8%A1%A8%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("搜索是在屋顶线上找更接近 \\(I_{\\star}\\) 的点：更好的 tile 提高复用、降低 bank conflict。它不改变算法复杂度。缓存命中后，decode 步不再付搜索。"),t("span",{class:"marginnote"},"数字实例：若对 \\(n=137\\)、\\(138\\)、\\(139\\)……各存一份配置，缓存几乎永远不命中。按 128 或 256 取整到桶后，几十种桶就能覆盖全部线上流量，热路径变成一次字典查询。"),e("连续批的形状抖动若跨越桶，会看到 TPOT 锯齿——应把桶做粗，或对混合批次用「最坏形状」配置换稳定性。"),t("span",{class:"marginnote"},"常见误区：以为自动调优是「上线前一次性跑完」。线上更常见的翻车是：来了没见过的新形状，现场扫网格几十秒，把这批请求的 TPOT 全部打穿。所以在线路径必须有搜索超时和回退安全配置，见下图。")],-1)),(l(),o(i,null,{default:E(()=>[A(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E6%96%B0%E5%BD%A2%E7%8A%B6%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20KEY%5B%22%E9%87%8F%E5%8C%96%E5%88%B0%E5%BD%A2%E7%8A%B6%E6%A1%B6%E4%BD%9C%E7%BC%93%E5%AD%98%E9%94%AE%22%5D%0A%20%20KEY%20--%3E%20HIT%7B%22%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%EF%BC%9F%22%7D%0A%20%20HIT%20--%3E%7C%E6%98%AF%7C%20RUN%5B%22%E7%94%A8%E7%BC%93%E5%AD%98%E9%85%8D%E7%BD%AE%E6%89%A7%E8%A1%8C%22%5D%0A%20%20HIT%20--%3E%7C%E5%90%A6%7C%20OK%7B%22%E5%85%81%E8%AE%B8%E7%8E%B0%E5%9C%BA%E6%90%9C%E7%B4%A2%EF%BC%9F%22%7D%0A%20%20OK%20--%3E%7C%22%E5%85%81%E8%AE%B8%EF%BC%8C%E9%99%90%E6%97%B6%22%7C%20TUNE%5B%22%E5%BF%AB%E9%80%9F%E6%90%9C%E7%B4%A2%E4%B8%80%E8%BD%AE%22%5D%0A%20%20OK%20--%3E%7C%E5%90%A6%7C%20FB%5B%22%E5%9B%9E%E9%80%80%E5%AE%89%E5%85%A8%E9%BB%98%E8%AE%A4%E9%85%8D%E7%BD%AE%22%5D%0A%20%20TUNE%20--%3E%20SAVE%5B%22%E5%86%99%E5%9B%9E%E7%BC%93%E5%AD%98%E4%BE%9B%E4%B8%8B%E6%AC%A1%E5%91%BD%E4%B8%AD%22%5D%0A%20%20SAVE%20--%3E%20RUN%0A%20%20FB%20--%3E%20RUN%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要每进程冷启动全网格（集群同时扩容会打满 GPU 做调优）。多卡要按 SKU 分缓存，A100 的最优不是 H100 的。下一课离开单核，处理 TP 的集合通信：自定义 allreduce。</p><p>出处：Chen et al., OSDI 2018；Zheng et al., OSDI 2020；Tillet et al., Triton, MAPL 2019。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>tile 与占用率是离散搜索，不是会计恒等式。</li><li>按形状桶离线调、热路径查表；验收数值。</li><li>布局与 dtype 必须进缓存键。</li><li>动态 \\(n\\) 要量化到桶，否则每步重搜。</li><li>FA 家族已调过的核不要再套一层网格。</li><li>下一课：TP 上的自定义 allreduce。</li><li>出处：Chen et al., 2018；Zheng et al., 2020。</li></ul>',5))])}const f=B(p,[["render",D]]);export{_ as __pageData,f as default};
